using System;
using System.Collections.Generic;
using UnityEngine;

namespace SpiritMovers.Text
{
    /// <summary>
    /// Per-font table binding <see cref="Core.Text.ThaiShaper"/> Private Use Area code points to the font's
    /// alternate glyph indices. Generated by the editor menu "Spirit Movers/Text/Build Thai Glyph Map".
    /// </summary>
    [CreateAssetMenu(menuName = "Spirit Movers/Text/Thai Glyph Map")]
    public sealed class ThaiGlyphMap : ScriptableObject
    {
        [Serializable]
        public struct Entry
        {
            public int Pua;
            public int Base;
            /// <summary>Alternate glyph index, or 0 when the font lacks it (the base character is used instead).</summary>
            public int GlyphIndex;
        }

        [SerializeField] private List<Entry> m_Entries = new();

        public IReadOnlyList<Entry> Entries => m_Entries;

        public void SetEntries(IEnumerable<Entry> entries)
        {
            m_Entries.Clear();
            m_Entries.AddRange(entries);
        }
    }
}
